TLM.f("Sancti/12-24s",{"officium":"In Vigilia Nativitatis Domini","rule":["no Gloria","Tempora none"],"sections":{"Introitus":[{"k":"ref","la":"Exod 16:6; 16:7"},{"k":"text","la":"Hódie sciétis, quia véniet Dóminus et salvábit nos: et mane vidébitis glóriam ejus."},{"k":"ref","la":"Ps 23:1"},{"k":"text","la":"Dómini est terra, et plenitúdo ejus: orbis terrárum, et univérsi, qui hábitant in eo."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Hódie sciétis, quia véniet Dóminus et salvábit nos: et mane vidébitis glóriam ejus."}],"Oratio":[{"k":"text","la":"Deus, qui nos redemptiónis nostræ ánnua exspectatióne lætíficas: præsta; ut Unigénitum tuum, quem Redemptórem læti suscípimus, veniéntem quoque Júdicem secúri videámus, Dóminum nostrum Jesum Christum, Fílium tuum:"},{"k":"macro","name":"Qui tecum"}],"Lectio":[{"k":"text","la":"Lectio Epístolæ beati Pauli Apostoli ad Romános"},{"k":"ref","la":"Rom 1:1-6"},{"k":"text","la":"Paulus, servus Jesu Christi, vocátus Apóstolus, segregátus in Evangélium Dei, quod ante promíserat per Prophétas suos in Scriptúris sanctis de Fílio suo, qui factus est ei ex sémine David secúndum carnem: qui prædestinátus est Fílius Dei in virtúte secúndum spíritum sanctificatiónis ex resurrectióne mortuórum Jesu Christi, Dómini nostri: per quem accépimus grátiam, et apostolátum ad obœdiéndum fídei in ómnibus géntibus pro nómine ejus, in quibus estis et vos vocáti Jesu Christi, Dómini nostri."}],"Graduale":[{"k":"ref","la":"Exod 16:6; 16:7"},{"k":"text","la":"Hódie sciétis, quia véniet Dóminus et salvábit nos: et mane vidébitis glóriam ejus."},{"k":"ref","la":"Ps 79:2-3"},{"k":"text","la":"Qui regis Israël, inténde: qui dedúcis, velut ovem, Joseph: qui sedes super Chérubim, appáre coram Ephraim, Bénjamin, et Manásse. Allelúja, allelúja."},{"k":"text","la":"Crástina die delébitur iníquitas terræ: et regnábit super nos Salvátor mundi. Allelúja.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 1:18-21"},{"k":"text","la":"Cum esset desponsáta Mater Jesu María Joseph, ántequam convenírent, invénta est in útero habens de Spíritu Sancto. Joseph autem, vir ejus, cum esset justus et nollet eam tradúcere, vóluit occúlte dimíttere eam. Hæc autem eo cogitánte, ecce, Angelus Dómini appáruit in somnis ei, dicens: Joseph, fili David, noli timére accípere Maríam cónjugem tuam: quod enim in ea natum est, de Spíritu Sancto est. Páriet autem fílium, et vocábis nomen ejus Jesum: ipse enim salvum fáciet pópulum suum a peccátis eórum."}],"Offertorium":[{"k":"ref","la":"Ps 23:7"},{"k":"text","la":"Tóllite portas, principes, vestras: et elevámini, portæ æternáles, et introíbit Rex glóriæ."}],"Secreta":[{"k":"text","la":"Da nobis, quǽsumus, omnípotens Deus: ut, sicut adoránda Fílii tui natalítia prævenímus, sic ejus múnera capiámus sempitérna gaudéntes:"},{"k":"macro","name":"Qui tecum"}],"Communio":[{"k":"ref","la":"Isa 40:5"},{"k":"text","la":"Revelábitur glória Dómini: et vidébit omnis caro salutáre Dei nostri."}],"Postcommunio":[{"k":"text","la":"Da nobis, quǽsumus, Dómine: unigéniti Fílii tui recensíta nativitáte respiráre; cujus cœlésti mystério páscimur et potámur."},{"k":"macro","name":"Per eundem"}]},"hr":{"4b2d8d0ccb3d4596":{"t":"Izl 16, 6-7, Ps 23, 1\n(Izl 16, 6-7) Danas ćete znati da dolazi Gospodin i da će nas spasiti a sutra ćete ugledati slavu njegovu. (Ps 23, 1) Gospodnja je zemlja i što je god na njoj, vasioni svijet i svi koji prebivaju na njemu.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>."},"b954cadf2a8aaab7":{"t":"<i>Pomolimo se</i>.\nBože, koji nas svake godine razveseljuješ iščekivanjem našeg otkupljenja, podaj da Jedinorođenoga Sina tvoga, koga radosno primamo kao Spasitelja, sigurni ugledamo i onda kad bude došao kao sudac. Gospodin naš, Isus Krist Sin tvoj.\n<i>Koji s Tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"d63a84c119a4e3da":{"t":"Rim 1, 1-6\nČitanje Poslanice bl. Pavla apostola Rimljanima. Braćo: Pavao, sluga Isusa Krista, pozvan za apostola, odijeljen za Božje evanđelje, koje je po svojim prorocima obećao prije u Svetom Pismu o svom Sinu Isusu Kristu Gospodinu našemu koji je kao čovjek iz Davidova roda, a u duhu svetosti po uskrsnuću od mrtvih preodređen silan Sin Božji. Po njemu smo primili milost i apostolstvo da njemu na čast prigrle vjeru svi narodi, među kojima ste i vi pozvanici Isusa Krista Gospodina našega.","v":"fratres → ∅"},"c520b1a15655cc91":{"t":"Izl 16, 6-7, Ps 79, 2-3\n(Izl 16, 6-7) Danas ćete znati da dolazi Gospodin i da će nas spasiti a sutra ćete ugledati slavu njegovu. (Ps 79, 2-3) Čuj, vladaru Izraelov, koji vodiš Josipovo pleme kao stado, koji stoluješ nad kerubinima, javi se pred Efraimom, Benjaminom i Manasijem.\n\n<i>Aleluja</i>, <i>aleluja</i>.\nSutrašnji će se dan uništiti bezakonje zemlje i nad nama će kraljevati Spasitelj svijeta. <i>Aleluja</i>."},"9eccaaf16939309e":{"t":"Mt 1, 18-21\nSlijedi sveto Evanđelje po Mateju. Kad je Isusova majka Marija bila zaručena s Josipom, prije nego se nastaniše zajedno, nađe se da je začela po Duhu Svetomu. Njezin muž Josip, jer je bio pravedan te je nije htio javno osramotiti, bavio se mišlju da je potajno otpusti. Ali, dok je on to razmišljao, ukaza mu se u snu anđeo i reče: Josipe, Davidov sine, nemoj se bojati uzeti k sebi svoju ženu Mariju, jer je ono što je u njoj začeto od Duha Svetoga. Ona će roditi Sina, i nadjeni mu ime Isus, jer će on spasiti svoj narod od njegovih grijeha."},"ac85b11ea65b2c24":{"t":"Ps 23, 7\nDignite se i otvorite se širom, vrata vječna, unići će Kralj slave."},"2ab707a60010ef0b":{"t":"Daj nam, molimo, svemogući Bože, kao što sada očekujemo časno rođenje Sina tvoga, tako da radosno primimo i vječne darove onoga:\n<i>koji s Tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"adad0f7f2fcbfa9b":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi. Gospodine, sveti Oče, svemogući vječni Bože. – Ti si s jedinorođenim Sinom tvojim i s Duhom Svetim jedan Bog, jedan Gospodin, ne u jedinstvu jedne osobe, već u Trojstvu jedine biti. Što naime po tvojoj objavi vjerujemo o tvojoj slavi, to isto bez razlike i razlučivanja vjerujemo i o tvome Sinu i o Duhu Svetome. Tako se u ispovijedanju istinitog i vjekovječnog božanstva klanjamo i vlastitosti osoba i jedinstvu biti i jednakosti veličanstva. – Koje hvale anđeli i arkanđeli, kerubini i serafini koji ne prestaju svaki dan klicati govoreći složnim glasom:"},"42f997fd24e75e85":{"t":"Iz 40, 5\nOtkrit će se slava Gospodnja i svaki će čovjek vidjeti spasenje Boga našega."},"17c993d0ae2d9952":{"t":"<i>Pomolimo se</i>.\nDaj nam, molimo te, Gospodine, da radosno svetkujemo spomen rođenja tvoga jedinorođenoga Sina koji nam daje ovo nebesko otajstvo za hranu i piće.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
